def cost_estimate(action_id):
    lower, upper, unit, basis, sources = COST_ESTIMATES[action_id]
    return {
        "lower": lower,
        "upper": upper,
        "unit": unit,
        "basis": basis,
        "sources": [{"title": title, "url": url} for title, url in (PRICE_SOURCES[key] for key in sources.split())],
    }
